	// The merge the server changes into the local variables based on the merge policy picked by the user.

	// Determine what type of merge the user requested
	var keepConflictingLocalChanges = false;
	if(tw.local.dataSectionBoundaryEventType === "KEEP_LOCAL")
		keepConflictingLocalChanges = true;
		
	merge(tw.local, keepConflictingLocalChanges); // Reset variables
	 
}); "]}},{"itemSubjectRef":"itm.12.c09c9b6e-aabd-4897-bef2-ed61db106297","documentation":[{"content":["This variable is bound to the Data Section coach view. This variable saves (stores) the original values of the variables on the client. The original values are used to determine how local or remote changes affected the variables on the client."],"textFormat":"text/plain"}],"name":"originalInput","isCollection":false,"declaredType":"dataObject","id":"2056.3605abf7-e4d7-47b5-9f0c-c8acd2235442"},{"itemSubjectRef":"itm.12.c09c9b6e-aabd-4897-bef2-ed61db106297","documentation":[{"content":["This variable is bound to the Data Section coach view. This variable contains the updated variable values from the server."],"textFormat":"text/plain"}],"name":"incomingChanges","isCollection":false,"declaredType":"dataObject","id":"2056.af758b9c-7c38-4aa0-855b-9a60499c7c9b"},{"itemSubjectRef":"itm.12.c09c9b6e-aabd-4897-bef2-ed61db106297","documentation":[{"content":["This variable is bound to the Data Section coach view. It contains the updated variable values from the coach."],"textFormat":"text/plain"}],"name":"localChanges","isCollection":false,"declaredType":"dataObject","id":"2056.96e581af-24db-4308-b2ab-75a8e24771fe"},{"startQuantity":1,"outgoing":["2027.939ffb16-34ae-45bc-b112-839b8e639b25"],"incoming":["2027.8184ed2f-f07d-40a5-8467-44a785dc0a89","2027.fa863d5b-7106-422d-8b09-c1561b72d547"],"default":"2027.939ffb16-34ae-45bc-b112-839b8e639b25","extensionElements":{"nodeVisualInfo":[{"width":95,"x":555,"y":406,"declaredType":"TNodeVisualInfo","height":70}]},"name":"Reset Pending Change Data","isForCompensation":false,"completionQuantity":1,"declaredType":"scriptTask","id":"2025.5578debd-dd2b-4562-b6e3-9e752ae2c0ec","scriptFormat":"text/x-javascript","script":{"content":["require([tw.local.helperScriptURL], function() { // Load the helper functions

