	// Calculate if there are any relevant incoming changes

	// There are unsaved changes . This can be detected by calling tw.system.coachUtils.hasLocallyChangedInputVars(). Here, however, this variable is
	// set by the Data Section coach view when it detects that a child view's data binding has changed.
	if(tw.local.unsavedLocalChanges === true || tw.system.coachUtils.hasLocallyChangedInputVars()){
		
		if(!tw.local.unsavedLocalChanges)
			tw.local.unsavedLocalChanges = true;
			
		// Call the helper function to update the incoming and local changes.
		checkIncomingChanges(tw.local, tw.system.coachUtils.getLocallyChangedVars(), tw.system.dataChangeUtils.getIncomingVars())		 
		
	} else if(tw.system.coachUtils.getLocallyChangedVars().length > 0) { // No pending changes to be merged, or local changes
	
		// Apply incoming changes to the local variables.
		tw.system.dataChangeUtils.applyAllIncomingVars();
		tw.local.incomingChangesMerged = true; // Signal that changes were applied automatically. The Data Section can listen and pop up a notification.
	 
	}

}); "]}},{"targetRef":"2025.ff61d212-4fa7-4877-a972-a708c8c6b764","extensionElements":{"linkVisualInfo":[{"sourcePortLocation":"rightCenter","showCoachControlLabel":false,"labelPosition":0.0,"targetPortLocation":"leftCenter","declaredType":"TLinkVisualInfo","saveExecutionContext":false,"showLabel":false}]},"name":"To Collect change information","declaredType":"sequenceFlow","id":"2027.deb868a5-98f7-42df-b117-346d162f0b49","sourceRef":"2025.9c55fda1-42a0-42ae-8e52-461641481dab"},{"targetRef":"2025.0673878c-4b92-4f47-8e2a-3a194fbc4c80","extensionElements":{"linkVisualInfo":[{"sourcePortLocation":"rightCenter","showCoachControlLabel":false,"labelPosition":0.0,"targetPortLocation":"leftCenter","declaredType":"TLinkVisualInfo","saveExecutionContext":false,"showLabel":false}]},"name":"To Stay on page","declaredType":"sequenceFlow","id":"2027.2b299aac-21e8-4ea0-9145-0184de0ba452","sourceRef":"2025.ff61d212-4fa7-4877-a972-a708c8c6b764"}],"startQuantity":1,"extensionElements":{"nodeVisualInfo":[{"width":95,"x":51,"y":463,"declaredType":"TNodeVisualInfo","height":70}]},"name":"Data Change","triggeredByEvent":true,"isForCompensation":false,"completionQuantity":1,"declaredType":"subProcess","id":"2025.1560b1a0-7291-49b5-ae9a-e7c4a16ca3d7"},{"targetRef":"2025.202527c8-2f61-40e7-a60c-67ff22d5ace1","extensionElements":{"linkVisualInfo":[{"sourcePortLocation":"topCenter","showCoachControlLabel":false,"labelPosition":0.0,"targetPortLocation":"leftCenter","declaredType":"TLinkVisualInfo","saveExecutionContext":false,"showLabel":true}]},"name":"Yes","declaredType":"sequenceFlow","id":"2027.575ee6ef-1981-4465-bf55-ccb7a3076db5","sourceRef":"2025.ab3cae26-6a87-4099-a718-0ba7c5dd6918"},{"startQuantity":1,"outgoing":["2027.5eeec417-a807-41cf-a9b6-ec6f0c9f2d23"],"incoming":["2027.4d0ffe87-7203-4d2e-88ae-af70589299b2"],"default":"2027.5eeec417-a807-41cf-a9b6-ec6f0c9f2d23","extensionElements":{"nodeVisualInfo":[{"width":95,"x":523,"y":103,"declaredType":"TNodeVisualInfo","height":70}]},"name":"Init Data Change Support","isForCompensation":false,"completionQuantity":1,"declaredType":"scriptTask","id":"2025.38df9d91-6e40-40e2-bc38-b5b7f66ec8ca","scriptFormat":"text/x-javascript","script":{"content":["require([tw.local.helperScriptURL], function() { // Load the helper functions

	// Initialize variables that support data change syncrhonization. 
	
	// This can only be done once the URL for the helper functions is returned by the 
	// Server Sice Init Data. Since this is can also be invoked as part of auto refresh the initialization
	// should only happen if the variables are undefined.
	
	if(tw.local.originalInput == undefined && tw.local.localChanges == undefined && tw.local.incomingChanges == undefined){
		initializeDataSyncronizationVariables(tw.local); // Intialize variables
	}
	
});

tw.local.paymentTerms = tw.epv.TermsAndConditions.paymentTerms;
tw.local.deliveryterms = tw.epv.TermsAndConditions.deliveryTerms;
tw.local.specialInstructions = tw.epv.TermsAndConditions.specialInstructions;
tw.local.instructions = tw.epv.TermsAndConditions.instructions; 

if(tw.local.ODCRequest.requestType.name == "closure"){
	tw.local.ClosureVis="READONLY";
	tw.local.ReversalVis="None";
}

if(tw.local.ODCRequest.requestType.name == "Reversal"){
	tw.local.ReversalVis="READONLY";
	tw.local.ClosureVis="None";
}
